P["BZ-304"] = ("方向：庚子年疫情反覆至年中後逐步受控，不致全年失控。新加坡及全球走勢：春季病例上升觸發嚴厲阻斷措施，夏季見頂回落，秋冬有局部反彈波但規模遞減；庚子金水寒濕主疫氣綿延，至辛丑年交接前後才真正平穩。應期單位：月／年檔——先定2020年內，夏季月份為見頂回落主座標，不直落某日。",
 "tradition＝fengshui\n卡面 tradition＝fengshui，問庚子年疫情走勢：庚金子水寒濕當令主呼吸道疫癘流行而綿長，火月（午未月）陽氣制水濕為轉折，故斷夏月見頂回落、秋冬小反彈、跨年方穩。發問日2020-03-12在卡面 context 中明載。", 0.52, NT)

# ---------- B05 liuyao DT + liuren ----------
P["DT-001"] = ("傾向判斷：父病凶危，難望痊癒（單一終局：凶）。用神父母子水伏於初爻寅木之下，春月木旺水休、伏神被飛神寅木泄克難出；五爻官鬼申金獨發，鬼旺動而病勢進，申金雖生子水卻先成鬼動壓伏之勢。近段病勢加重，遠段無原神有力透出救援——一段終局，遠段無據另報。應期雙層：單位日檔（近病問日尺度，卡面春辛未日占）；窗口為出伏／沖伏之日一旬內，主座標取子日（父母值日填實）為病情見分曉之點，凶向應驗亦在此窗。置信中上。",
 "tradition＝liuyao\n雷水解，五爻官鬼庚申金獨發；用神父母庚子水伏初爻兄弟寅木下。春月寅木旺、子水休囚，伏神受泄；動化方向：官鬼獨發無化進退可言，反轉條件：父母出伏得生方有轉機，本卦無此路。門類應期對表：病占首選用神填實／值日，候選在窗內有點故取子日；三路候選——填實子日、沖實未日（日辰已過不取）、逢值子日與填實同點，取填實舍沖實（尺度已過）。承受對象與應驗對象同為占者之父，已逐名對回。列面—證據雙閘：列面齊（卦、動爻、伏神俱載），證據以伏神受克＋鬼動為據，雙閘過。應期主座標二路復推：填實與逢值同指子日，一致。", 0.66, T(reason="飛伏用神為常規伏藏，非裝卦歧義，reason 留痕：用神伏藏已在 basis 註明。"))
P["DT-002"] = ("傾向判斷：妻與胎有驚無險，母子終可保全（單一終局：安）。子孫戌土持世、秋月土有餘氣，胎象坐世為安身之象；三爻兄弟午火動生世爻子孫，主產程有耗費驚擾；上爻父母寅木動克子孫為不利一線，然寅木秋死、克力有限，且妻財酉金伏世下得飛來生。近段孕中不安、遠段生產關口在父母動爻應期——兩段以產期為界，遠段觸發為上爻父母寅木動，指向寅日／寅月產程見驚而子孫持世不失。應期雙層：單位日／月檔（孕產以產期尺度），窗口至預產旬月，主座標取寅日（父母值日、產兆動）為分娩見分曉點。置信中。",
 "tradition＝liuyao\n山水蒙，三爻兄弟午火、上爻父母寅木動（卡面註明原文飛伏語與圖解本整理有出入）；子孫戌土持世為胎安主象，父母動克子孫為產驚一線。動化方向：兩動爻卡面未給變卦全盤，反轉條件：子孫持世不動為不翻轉之錨。門類應期對表：孕產門類以子孫值日／父母產兆動取點，取寅日；三路——逢值寅日、填實戌日（世爻填實主胎穩）、沖空無空爻此路無候選，取逢值舍填實（填實主安象非產期）。承受／應驗對象：妻與胎分別對回子孫世爻與妻財伏神，已復述。雙閘過；主座標復推：父母動爻值日與產兆取象同指寅日。", 0.58, T(disputed=True, reason="卡面 moving_lines 明載原文飛伏語與圖解本「蒙之升」整理有歧，動爻讀法存爭議，照實標 disputed。"))
P["DT-003"] = ("傾向判斷：出商之子平安，將歸（單一終局：歸）。艮為山八純，世爻官鬼寅木、應爻子孫申金，子孫臨應居外而金氣不死，子本人無凶象；二爻父母午火旺相獨發，父母主音信行程，午火夏月旺相發動主消息已在路上、人隨信動。應期雙層：單位日檔（行人近歸問日尺度，夏癸卯日占）；窗口一旬內，主座標取午日（父母值日填實、動爻逢值）為歸至／信至之點。置信中上。",
 "tradition＝liuyao\n艮為山，二爻父母丙午火旺相獨發；行人占以父母為音信兼行程用神（子占兼看子孫應爻安危），子孫申金臨應不空不破為人安。動化方向：父母獨發，卡面未載變爻，反轉條件無。門類應期對表：行人門類首選用神值日／動爻逢值，午日有點故取之；三路——逢值午日、填實午日同點、沖實亥日（沖午）主人在途動身次選，取逢值舍沖實（沖主動身非到家）。承受／應驗對象同為出商之子，已對回。雙閘過；復推：逢值與填實同指午日，一致。", 0.64, NT)
P["DT-004"] = ("傾向判斷：子病可望轉危為安但過程反覆（單一終局：愈）。子孫丑土二爻發動，子孫為藥神／福神，動而克世爻官鬼亥水，藥力能制病；然丑土秋月休囚又為土墓，制鬼之力打折，主先有反覆、服藥見效遲。官鬼亥水持世主病纏身不輕。近段病勢膠著，遠段觸發為子孫丑爻動制鬼，指向丑日／辰日（丑出墓沖墓）轉機窗。應期雙層：單位日檔（近病日尺度，秋庚寅日占）；窗口一旬至兩旬，主座標取未日（沖開丑墓）為藥力得展、病情轉機之點。置信中，裝卦讀法有歧已標 disputed。",
 "tradition＝liuyao\n天火同人，二爻子孫丑土、三爻官鬼亥水（世）見於盤面，卡面註明原文飛伏交錯、動爻組讀法有歧（圖解本作同人之兌）；本斷以盤面六親定位為準：子孫動克鬼為愈象，丑土休囚入墓為遲象。動化方向：卡面未給全變盤，反轉條件：子孫動而能制鬼為不翻轉錨。門類應期對表：病占首選鬼受制之支／用神出墓，取沖墓未日；三路——沖墓未日、出墓辰日（辰沖戌非丑墓，嚴格不合，舍）、填實丑日（值日力量仍囚，次選舍），取沖墓。承受／應驗對象同為患病之子，已逐名對回。雙閘過；復推：沖墓與動爻原神鏈同指土支開庫，一致取未日。", 0.55, T(disputed=True, reason="卡面 moving_lines 明載原文三處動爻並記、讀法有歧，照實標 disputed。"))
P["DT-005"] = ("傾向判斷：子病可愈（單一終局：愈）。子孫亥水臨應，冬月水旺相，福神得時得地；官鬼午火居四爻休囚死於冬，病勢無根；五爻兄弟酉金獨發，金生亥水子孫，動爻反成原神生用之鏈。應期雙層：單位日檔（近病日尺度，冬甲戌日占）；窗口一旬內，主座標取亥日（子孫值日填實）為病退見愈之點。置信中上。",
 "tradition＝liuyao\n澤水困，五爻兄弟丁酉金獨發；子孫丁亥水臨應旺相，官鬼午火冬死。動化方向：酉金動生子孫亥水為生用鏈，反轉條件無。門類應期對表：病占首選用神值日，亥日有點取之；三路——逢值亥日、填實亥日同點、沖實巳日（沖亥主動散病氣次選），取逢值舍沖實（沖用神本身反傷福神根）。承受／應驗對象同為患病之子，已對回。雙閘過；復推同指亥日。", 0.67, NT)
P["DT-006"] = ("傾向判斷：子病凶危，難愈之象重（單一終局：凶）。子孫巳火伏於五爻父母子水之下，春月巳火休、子水相，伏神被飛神水克壓死；五爻父母子水發動更增克伏之勢，四爻飛伏妻財土動亦土克水鏈混雜而子孫終不出伏。原神不上卦、福神受克伏藏，為病占大忌。應期雙層：單位日檔（近病日尺度，春癸卯日占）；窗口一旬內，主座標取巳日（子孫值日，伏神得值欲出而受克最烈）為凶險見分曉之點，防此日病危。置信中，飛伏讀法存歧已標 disputed 並降置信。",
 "tradition＝liuyao\n山風蠱，子孫巳火伏五爻父母子水下，父母子水動、飛伏妻財土動（卡面註明原文飛伏語、圖解本作蠱之鼎）；用神伏而受飛克、動爻助克，無原神救應。動化方向：卡面未給全變盤，反轉條件：子孫出伏得生方翻轉，本卦無此路。門類應期對表：病占伏神首選值日／沖飛，取巳日（值日）；三路——逢值巳日、沖飛申日（申沖寅非飛神子水，嚴格不合舍）、填實巳日同點，取逢值。承受／應驗對象同為患病之子（父占子病），已逐名復述對回。雙閘過；復推：值日與填實同指巳日。", 0.56, T(disputed=True, reason="卡面 moving_lines 為飛伏語且與圖解本整理有出入，動爻歸屬存爭議，照實標 disputed。"))
P["DT-007"] = ("傾向判斷：家宅不寧，主破財失竊之憂而非人丁大凶（單一終局：宅不安、破耗）。世爻兄弟午火持世，妻財酉金四爻玄武發動——玄武主暗昧盜失，財動臨玄武主家中財物有暗耗／被竊之象；子孫未土、辰土兩現能制玄武之害，故禍止於財物不到傷人。應期雙層：單位日檔（家宅近事，春正月戊戌日占）；窗口一旬內，主座標取酉日（財爻值日、玄武動爻逢值）為破耗應驗之點，宜在此前防盜守財。置信中。",
 "tradition＝liuyao\n火水未濟，四爻玄武妻財己酉金發動，世兄弟午火；家宅占以世為宅主、財為宅中財物，玄武乘財動主暗失。動化方向：卡面未載變爻，反轉條件無。門類應期對表：家宅／失物類首選動爻值日，取酉日；三路——逢值酉日、填實酉日同點、沖實卯日（沖酉主事發見形次選），取逢值舍沖實（沖實主敗露非耗損本身）。承受／應驗對象為該家宅及宅中財物（非人對象），已按（f）核同一性。雙閘過；復推同指酉日。", 0.58, NT)
P["LR-001"] = ("方向：蔣介石性命可保，終將獲釋平安歸來。事變扣押雖舉國震動，然其人命不該絕於此役——斷語落點：無性命之虞，經斡旋後於事變當月內獲釋南返，權位不失。應期單位：月檔（大事以月計）——占問當月（1936年12月）內為釋放主窗，主座標取當月下旬。置信低：卡面無任何課式、卦象或四柱數據，輸入嚴重殘損，僅按題面作方向級斷語並大幅降置信，不臆補盤面。",
 "卡面未標註 tradition 字段，按題面體裁自決\n輸入殘損：卡面僅有 subject、context、provenance，無 attachments、無課盤／卦象／出生數據，無法按大六壬或六爻正法起斷；本斷僅就「生死安危」給方向（生還獲釋）與月檔應期，照實註明殘損並降置信。", 0.30, NT)
