def write_batch(name):
    ids = BATCHES[name]
    assert len(ids) == 20, (name, len(ids))
    for cid in ids:
        assert cid in P, f"missing {cid}"
        pt, basis, conf, trig = P[cid]
        assert 0.0 <= conf <= 1.0
        assert set(trig.keys()) == {"changed_main","reserve_used","disputed","reason"}
        assert all(isinstance(trig[k], bool) for k in ("changed_main","reserve_used","disputed"))
        assert isinstance(trig["reason"], str)
        obj = {"case_id": cid, "prediction_text": pt, "basis": basis, "confidence": conf, "trigger": trig}
        assert set(obj.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
        (OUT / f"{cid}.json").write_text(json.dumps(obj, ensure_ascii=False, indent=1), encoding="utf-8")
    print(name, "written", len(ids), "ids_ok", set(ids) == {P[k] and k for k in ids})

for b in ("B04","B05","B06"):
    write_batch(b)

# final counts (only own batch ids, no glob over others)
allids = BATCHES["B04"]+BATCHES["B05"]+BATCHES["B06"]
cm = ru = di = 0
n = 0
for cid in allids:
    d = json.loads((OUT / f"{cid}.json").read_text(encoding="utf-8"))
    n += 1
    cm += d["trigger"]["changed_main"]; ru += d["trigger"]["reserve_used"]; di += d["trigger"]["disputed"]
print("TOTAL", n, "changed_main", cm, "reserve_used", ru, "disputed", di)
